SELECT    
    car_contact_id,
    car_id,
    car_company,
    salutation,
    first_name,
    last_name,
    email,
    phone,
    contact_address,
    zip,
    city, 
    contact_comment, 
    contact_type,
    contact_subtype, 
    DATETIME(cp.created_at, cmt.country_timezone) as created_at,
	DATETIME(cp.updated_at, cmt.country_timezone) as updated_at,
	DATETIME(cp.deleted_at, cmt.country_timezone) as deleted_at,
    created_by_id,
    created_by,
    updated_by_id,
    updated_by,
    deleted_by_id,
    deleted_by,
    tax_id,
    bank_account_owner,
    bank_code,
    bank_account_number,
    bank_name,
    account_type,
    bank_account_owner_tax_id,
    bank_account_details,
    occupation,
    marital_status,
    selling_reason,
    referrer_code,
    country_id   
FROM `{{params.project_name}}.staging.CarContacts` cp
INNER JOIN `{{params.project_name}}.staging.CountryMetadata` cmt using (country_id)
where updated_at >= '{{params.start_ts}}' and updated_at < '{{params.end_ts}}'